@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=Rajdhani:wght@400;500;600;700&display=swap');
:root{font-family:'Rajdhani',sans-serif;color:#eef2e8;background:#080b0c;font-synthesis:none;text-rendering:optimizeLegibility;--acid:#c7e37c;--orange:#f07a49;--muted:rgba(222,231,216,.55)}*{box-sizing:border-box}html,body,#game{width:100%;height:100%;margin:0;overflow:hidden}body{background:#080b0c;touch-action:none;user-select:none;-webkit-user-select:none}#game{position:fixed;inset:0}canvas{display:block;width:100%;height:100%;outline:0}.vignette{position:fixed;inset:0;pointer-events:none;z-index:2;background:radial-gradient(ellipse at center,transparent 35%,rgba(0,0,0,.2) 76%,rgba(0,0,0,.68) 145%);box-shadow:inset 0 0 150px rgba(0,0,0,.48)}.vignette:after{content:'';position:absolute;inset:0;opacity:.11;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.23'/%3E%3C/svg%3E")}.screen{position:fixed;inset:0;z-index:5;display:flex;align-items:center;justify-content:center;background:linear-gradient(90deg,rgba(5,9,10,.88) 0%,rgba(5,9,10,.56) 44%,rgba(5,9,10,.04) 100%),linear-gradient(0deg,rgba(4,7,8,.64),transparent 40%),radial-gradient(ellipse at 68% 47%,transparent 0%,rgba(0,0,0,.18) 70%)}.screen:before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,rgba(203,227,124,.035) 1px,transparent 1px),linear-gradient(rgba(203,227,124,.035) 1px,transparent 1px);background-size:70px 70px;mask-image:linear-gradient(90deg,#000,transparent 75%);opacity:.35}.screen-grain{position:absolute;inset:0;opacity:.14;pointer-events:none;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.4'/%3E%3C/svg%3E")}.screen-content{position:relative;width:min(560px,90vw);margin-left:max(7vw,34px);margin-right:auto;animation:arrive .8s cubic-bezier(.15,.7,.2,1) both}.eyebrow{display:flex;align-items:center;gap:12px;color:var(--acid);font:600 11px 'Rajdhani',sans-serif;letter-spacing:.19em}.eyebrow span{display:inline-block;width:25px;height:1px;background:var(--acid);opacity:.75}.screen h1{font:900 clamp(74px,11vw,142px)/.8 'Barlow Condensed',sans-serif;letter-spacing:-.055em;margin:28px 0 0;text-shadow:0 6px 45px rgba(0,0,0,.55)}.screen h1 span{display:block;color:var(--acid)}.subtitle{font:700 19px 'Rajdhani',sans-serif;letter-spacing:.47em;margin:21px 0 30px 6px;color:#d9ded0}.story{font:500 17px/1.35 'Rajdhani',sans-serif;letter-spacing:.04em;color:rgba(235,240,229,.74);margin:0 0 35px 5px}.primary-button{position:relative;display:flex;align-items:center;justify-content:space-between;width:212px;height:58px;padding:0 20px 0 25px;border:1px solid rgba(207,229,144,.75);background:rgba(186,213,104,.11);color:#eaf1dd;cursor:pointer;font:700 15px 'Rajdhani',sans-serif;letter-spacing:.2em;transition:.2s;clip-path:polygon(0 0,92% 0,100% 24%,100% 100%,8% 100%,0 77%)}.primary-button:before{content:'';position:absolute;inset:0;background:var(--acid);transform:scaleX(0);transform-origin:left;transition:transform .24s;z-index:-1}.primary-button:hover{color:#111;box-shadow:0 0 35px rgba(196,227,124,.18)}.primary-button:hover:before{transform:scaleX(1)}.primary-button b{font-size:23px;font-weight:500;color:var(--acid)}.primary-button:hover b{color:#111}.start-meta{margin-top:37px;color:rgba(222,231,216,.63);font:600 10px 'Rajdhani',sans-serif;letter-spacing:.13em}.start-meta span{color:var(--orange);font-size:15px;vertical-align:-2px;margin-right:8px}.start-meta i{display:inline-block;width:3px;height:3px;background:var(--acid);border-radius:50%;margin:0 11px 2px}.desktop-instructions,.mobile-instructions{margin-top:44px;color:rgba(222,231,216,.45);font:500 11px 'Rajdhani',sans-serif;letter-spacing:.07em}.desktop-instructions span,.mobile-instructions span{color:var(--acid);padding:0 5px}.mobile-instructions{display:none}.version-tag{position:absolute;bottom:25px;right:32px;color:rgba(222,231,216,.38);font:600 9px 'Rajdhani',sans-serif;letter-spacing:.16em}.version-tag span{color:var(--acid);padding:0 8px}.hidden{display:none!important}.hud{position:fixed;inset:0;z-index:3;pointer-events:none;color:#eef2e8}.topbar{position:absolute;top:0;left:0;right:0;height:79px;padding:0 4.5vw;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(6,9,9,.78),rgba(6,9,9,.24));border-bottom:1px solid rgba(223,230,212,.08)}.brand{display:flex;align-items:center;gap:11px}.brand-mark{width:34px;height:34px;border:1px solid rgba(205,228,129,.65);display:grid;place-items:center;color:var(--acid);font:800 13px 'Barlow Condensed';transform:skew(-6deg)}.brand b{display:block;font:800 15px 'Barlow Condensed';letter-spacing:.15em}.brand small,.wave-card small,.objective small{display:block;color:rgba(230,235,223,.46);font:600 9px 'Rajdhani';letter-spacing:.14em;margin-top:1px}.wave-card{display:flex;align-items:center;gap:11px}.live-dot,.status-dot{width:6px;height:6px;background:var(--acid);box-shadow:0 0 10px var(--acid);border-radius:50%}.wave-card b{display:block;margin-top:1px;font:700 15px 'Barlow Condensed';letter-spacing:.1em}.objective{text-align:right}.objective b{display:block;font:700 11px 'Rajdhani';letter-spacing:.1em;margin-top:2px}.hud-left{position:absolute;left:4.5vw;bottom:45px;width:210px}.health-label{display:flex;justify-content:space-between;align-items:center;font:700 11px 'Rajdhani';letter-spacing:.15em}.health-label span{color:rgba(235,240,229,.57)}.health-label b{font:700 20px 'Barlow Condensed';color:var(--acid)}.health-track{height:3px;background:rgba(240,240,230,.19);margin-top:7px}.health-track i{height:100%;display:block;width:100%;background:var(--acid);box-shadow:0 0 9px rgba(199,227,124,.7);transition:width .2s,background .2s}.status-line{margin-top:10px;font:600 9px 'Rajdhani';letter-spacing:.11em;color:rgba(230,235,223,.53)}.status-dot{display:inline-block;width:5px;height:5px;margin:0 7px 1px 0}.hud-right{position:absolute;right:4.5vw;bottom:40px;text-align:right}.ammo-count{font:700 51px/.8 'Barlow Condensed';letter-spacing:-.02em}.ammo-count i{font-style:normal;color:rgba(235,240,229,.33);font-weight:400;font-size:30px;margin:0 4px}.ammo-count small{font-size:22px;color:rgba(235,240,229,.5)}.weapon-name{font:700 12px 'Rajdhani';letter-spacing:.14em;margin-top:8px}.weapon-name span{color:var(--acid);font-size:9px;margin-left:5px}.ammo-rule{height:1px;background:linear-gradient(90deg,transparent,rgba(199,227,124,.65));margin:8px 0}.hint-reload{font:700 12px 'Rajdhani';color:var(--acid)}.hint-reload span{color:rgba(230,235,223,.46);letter-spacing:.12em;margin-left:6px;font-size:9px}.crosshair{position:absolute;left:50%;top:50%;width:18px;height:18px;transform:translate(-50%,-50%);opacity:.9}.crosshair i{position:absolute;width:3px;height:3px;border:1px solid rgba(235,241,222,.92)}.crosshair i:nth-child(1){top:0;left:0}.crosshair i:nth-child(2){top:0;right:0}.crosshair i:nth-child(3){bottom:0;left:0}.crosshair i:nth-child(4){bottom:0;right:0}.crosshair b{position:absolute;left:8px;top:8px;width:2px;height:2px;background:var(--acid)}.hitmarker{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) scale(.5);font:400 27px 'Rajdhani';color:#f4ead1;opacity:0;text-shadow:0 0 8px rgba(255,235,193,.8);transition:.08s}.hitmarker.show{opacity:1;transform:translate(-50%,-50%) scale(1)}.wave-banner{position:absolute;left:50%;top:26%;transform:translate(-50%,-12px);text-align:center;opacity:0;transition:.35s}.wave-banner.show{opacity:1;transform:translate(-50%,0)}.wave-banner span{display:block;color:var(--orange);font:700 10px 'Rajdhani';letter-spacing:.35em}.wave-banner b{font:800 clamp(28px,5vw,47px) 'Barlow Condensed';letter-spacing:.08em;text-shadow:0 3px 20px #000}.damage-flash{position:absolute;inset:0;opacity:0;background:radial-gradient(ellipse at center,transparent 30%,rgba(181,34,25,.5));transition:opacity .15s}.controls-hint{position:absolute;bottom:18px;left:50%;transform:translateX(-50%);color:rgba(226,233,218,.35);font:600 9px 'Rajdhani';letter-spacing:.12em;white-space:nowrap}.controls-hint span{color:var(--acid);padding:0 6px}.pause-button{pointer-events:auto;position:absolute;right:24px;top:95px;background:rgba(4,7,7,.25);border:1px solid rgba(220,230,210,.26);color:rgba(240,244,232,.7);width:35px;height:35px;font:15px 'Rajdhani';cursor:pointer}.mobile-controls{display:none}.end-content{text-align:left}.screen h2{font:800 clamp(38px,7vw,70px)/.9 'Barlow Condensed';margin:27px 0 13px;letter-spacing:.02em}.end-content>p{color:var(--muted);font-size:16px;margin-bottom:32px}.final-score{display:flex;align-items:center;gap:18px;margin:0 0 30px}.final-score small{font:600 10px 'Rajdhani';color:var(--muted);letter-spacing:.16em}.final-score b{font:800 36px 'Barlow Condensed';color:var(--acid)}@keyframes arrive{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:700px){.screen{background:linear-gradient(90deg,rgba(5,9,10,.86),rgba(5,9,10,.38)),linear-gradient(0deg,rgba(4,7,8,.75),transparent 60%)}.screen-content{margin-left:7vw;width:86vw}.screen h1{font-size:clamp(76px,21vw,120px);margin-top:24px}.subtitle{font-size:15px;margin-top:17px;margin-bottom:22px}.story{font-size:15px;margin-bottom:26px}.primary-button{width:190px;height:53px}.start-meta{margin-top:26px;font-size:9px}.desktop-instructions{display:none}.mobile-instructions{display:block;margin-top:24px;font-size:9px}.version-tag{right:18px;bottom:17px;font-size:8px}.topbar{height:61px;padding:0 18px}.brand-mark{width:29px;height:29px;font-size:11px}.brand b{font-size:13px}.brand small{font-size:7px}.wave-card{gap:7px}.wave-card b{font-size:13px}.wave-card small{font-size:7px}.objective{display:none}.hud-left{left:18px;bottom:29px;width:130px}.hud-right{right:18px;bottom:27px}.health-label{font-size:9px}.health-label b{font-size:18px}.status-line{font-size:7px;margin-top:8px}.ammo-count{font-size:43px}.ammo-count small{font-size:17px}.weapon-name{font-size:10px}.controls-hint{display:none}.pause-button{top:72px;right:16px;width:31px;height:31px}.mobile-controls{display:block;position:absolute;inset:0;pointer-events:none}.joystick{position:absolute;bottom:78px;left:24px;width:112px;height:112px;pointer-events:auto;touch-action:none}.joy-ring{position:absolute;inset:0;border:1px solid rgba(225,235,215,.27);border-radius:50%;background:rgba(8,12,12,.2);box-shadow:inset 0 0 25px rgba(0,0,0,.16)}.joy-knob{position:absolute;left:50%;top:50%;width:43px;height:43px;border-radius:50%;transform:translate(-50%,-50%);background:rgba(198,223,131,.21);border:1px solid rgba(203,227,130,.65);box-shadow:0 0 18px rgba(199,227,124,.1)}.joystick span{position:absolute;left:50%;top:calc(100% + 8px);transform:translateX(-50%);font:600 8px 'Rajdhani';letter-spacing:.2em;color:rgba(230,235,220,.45)}.look-zone{position:absolute;right:0;top:70px;bottom:170px;width:58%;pointer-events:auto;touch-action:none}.touch-button{position:absolute;pointer-events:auto;touch-action:none;display:flex;align-items:center;justify-content:center;border-radius:50%;color:#edf4df;border:1px solid rgba(210,230,157,.66);background:rgba(19,26,20,.48);box-shadow:0 0 22px rgba(0,0,0,.32);font:700 10px 'Rajdhani';letter-spacing:.1em}.fire-button{right:24px;bottom:88px;width:72px;height:72px;background:rgba(153,181,80,.2);border-color:rgba(207,232,140,.82);flex-direction:column;gap:1px}.fire-icon{font-size:20px;line-height:20px;color:var(--acid)}.reload-button{right:104px;bottom:43px;width:44px;height:44px;font-size:20px;flex-direction:column}.reload-button small{font-size:6px;letter-spacing:.1em}.wave-banner{top:23%}.hitmarker{font-size:22px}}
@media(max-height:500px) and (orientation:landscape){.mobile-controls .joystick{bottom:42px;width:90px;height:90px}.joy-knob{width:35px;height:35px}.fire-button{bottom:41px;width:60px;height:60px}.reload-button{bottom:25px;right:87px;width:38px;height:38px}.hud-left,.hud-right{bottom:15px}.topbar{height:49px}.pause-button{top:56px}.screen h1{font-size:82px;margin-top:15px}.subtitle{margin:12px 0 14px}.story{font-size:13px;margin-bottom:16px}.primary-button{height:45px}.start-meta{margin-top:15px}.mobile-instructions{margin-top:12px}}

import * as THREE from 'three';
import './style.css';

const $ = (id) => document.getElementById(id);
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x171b1b);
scene.fog = new THREE.FogExp2(0x171b1b, 0.021);
const camera = new THREE.PerspectiveCamera(73, innerWidth / innerHeight, 0.08, 100);
camera.position.set(0, 1.68, 0);
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.65));
renderer.setSize(innerWidth, innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.14;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
$('game').appendChild(renderer.domElement);

const hemi = new THREE.HemisphereLight(0xa6b2a1, 0x34362f, 1.5); scene.add(hemi);
const moon = new THREE.DirectionalLight(0xb7c5c6, 2.15); moon.position.set(-7, 13, 5); moon.castShadow = true;
moon.shadow.mapSize.set(1024, 1024); moon.shadow.camera.left = -22; moon.shadow.camera.right = 22; moon.shadow.camera.top = 22; moon.shadow.camera.bottom = -22; moon.shadow.bias = -0.001; scene.add(moon);
const orangeLight = new THREE.PointLight(0xff6438, 24, 21, 2); orangeLight.position.set(7, 3.2, -8); scene.add(orangeLight);
const blueLight = new THREE.PointLight(0x7d9eae, 11, 17, 2); blueLight.position.set(-9, 3.4, 3); scene.add(blueLight);

const mat = (color, roughness = .88, metalness = 0) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const concrete = [mat(0x55554c), mat(0x464941), mat(0x5b574c)];
const asphalt = mat(0x272b29); const rust = mat(0x795141, .78, .35); const metal = mat(0x343c3a, .38, .72);
const floor = new THREE.Mesh(new THREE.PlaneGeometry(52, 52), asphalt); floor.rotation.x = -Math.PI / 2; floor.receiveShadow = true; scene.add(floor);
// Broken markings, cracks and gravel turn the simple arena into a readable abandoned street.
const roadLine = new THREE.MeshStandardMaterial({ color: 0x9b865e, roughness: 1, transparent: true, opacity: .43 });
for (let i = 0; i < 10; i++) { const stripe = new THREE.Mesh(new THREE.BoxGeometry(.12, .012, 1.4), roadLine); stripe.position.set((i % 2 ? 1 : -1) * (1.7 + Math.random() * .28), .009, -13 + i * 2.8); scene.add(stripe); }
const debrisMat = [mat(0x777363), mat(0x3e403c), mat(0x6a4839)];
for (let i = 0; i < 125; i++) { const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(.06 + Math.random() * .12, 0), debrisMat[i % 3]); rock.position.set((Math.random() - .5) * 42, .035 + Math.random() * .025, (Math.random() - .5) * 42); rock.rotation.set(Math.random() * 3, Math.random() * 3, Math.random() * 3); rock.scale.y = .3 + Math.random() * .5; rock.castShadow = true; scene.add(rock); }

function box(parent, size, material, pos, rot = [0,0,0], cast = true) { const m = new THREE.Mesh(new THREE.BoxGeometry(...size), material); m.position.set(...pos); m.rotation.set(...rot); m.castShadow = cast; m.receiveShadow = true; parent.add(m); return m; }
function makeBuilding(x, z, w, h, d, seed = 0) {
  const g = new THREE.Group(); g.position.set(x, 0, z); scene.add(g);
  const body = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), concrete[seed % 3]); body.position.y = h / 2; body.castShadow = true; body.receiveShadow = true; g.add(body);
  // jagged collapsed roofline
  for (let i = 0; i < 4; i++) { const chunk = box(g, [.5 + Math.random() * 1.4, .45 + Math.random() * .9, d + .1], concrete[(seed + i + 1) % 3], [-w / 2 + i * (w / 3), h + .1 + Math.random() * .18, 0], [0,0,(Math.random() - .5) * .12]); }
  const winMat = new THREE.MeshStandardMaterial({ color: 0x151b1c, roughness: .4, metalness: .15, emissive: 0x111515 });
  for (let side = -1; side <= 1; side += 2) for (let j = 0; j < Math.floor(w / 2.7); j++) {
    const wx = -w / 2 + 1.3 + j * 2.5; const wy = 1.7 + (j % 2) * 2;
    if (wy < h - .6) { const win = new THREE.Mesh(new THREE.BoxGeometry(.85, 1.1, .05), winMat); win.position.set(wx, wy, side * (d / 2 + .03)); g.add(win); box(g, [.07,1.22,.1], concrete[0], [wx,wy,.04 + side * d / 2]); }
  }
  return g;
}
makeBuilding(-18, -6, 8, 9, 9, 1); makeBuilding(17, -10, 9, 12, 8, 2); makeBuilding(-18, 15, 7, 7, 9, 0); makeBuilding(19, 15, 8, 8, 8, 1);
// Ruined perimeter walls and industrial silhouettes.
for (const [x,z,w,d,h] of [[0,-24,52,1,5],[-25,0,1,50,5],[25,0,1,50,5],[0,24,52,1,5]]) { const wall = box(scene,[w,h,d],concrete[1],[x,h/2,z]); }
for (let i=0;i<13;i++) { const x=-20+i*3.35; const pole=box(scene,[.12,4,.12],metal,[x,2,-23.25]); const wire=box(scene,[3.2,.045,.045],metal,[x+1.6,3.8,-23.25],[0,0,.03]); }
// wrecked vehicles as chunky, layered silhouettes
function makeVehicle(x,z,rot=0) { const g=new THREE.Group(); g.position.set(x,0,z);g.rotation.y=rot;scene.add(g);box(g,[3.6,.72,1.65],mat(0x454947),[0,.62,0],[0,0,-.05]);box(g,[2.1,.78,1.4],mat(0x353b3a),[-.25,1.26,0],[0,0,-.06]);box(g,[1.6,.48,1.46],mat(0x1d2829,.28,.25),[-.25,1.32,0]);for(const wx of [-1.25,1.25])for(const wz of [-.84,.84]){const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.39,.39,.2,12),mat(0x171918));wheel.rotation.z=Math.PI/2;wheel.position.set(wx,.42,wz);wheel.castShadow=true;g.add(wheel);}box(g,[.18,.2,.08],mat(0x9c5e40,.3),[1.82,.76,-.38]);return g;}
makeVehicle(-7,-12,.14); makeVehicle(9,8,-.4);
// Burning barrel and warning sign provide warm/cool contrast and orientation.
function barrel(x,z) { const b=new THREE.Mesh(new THREE.CylinderGeometry(.48,.53,1.22,12),rust);b.position.set(x,.61,z);b.castShadow=true;b.receiveShadow=true;scene.add(b);for(let y of [.27,.78]){const band=new THREE.Mesh(new THREE.TorusGeometry(.5,.045,6,16),metal);band.rotation.x=Math.PI/2;band.position.set(x,y,z);scene.add(band);}return b; }
barrel(7,-7); barrel(-12,10);
const signMat = new THREE.MeshStandardMaterial({color:0xb44331,roughness:.65,emissive:0x240600});box(scene,[2.4,.95,.12],signMat,[-10,2.4,-19]);
const signText = new THREE.Mesh(new THREE.PlaneGeometry(2.15,.62), new THREE.MeshBasicMaterial({color:0xffb79a,side:THREE.DoubleSide}));signText.position.set(-10,2.4,-18.92);scene.add(signText);
// Simple distant skyline and haze silhouettes.
const skylineMat=mat(0x242a28);for(let i=0;i<17;i++){const w=2+Math.random()*4,h=5+Math.random()*12;const s=new THREE.Mesh(new THREE.BoxGeometry(w,h,1.5),skylineMat);s.position.set(-25+i*3.2,h/2,-25.5);scene.add(s);}

// First-person rifle: layered receiver, rail, sights, barrel, magazine and moving bolt.
const gun = new THREE.Group(); camera.add(gun); gun.position.set(.35,-.32,-.64); gun.rotation.set(-.04,-.04,0);
const gunBody=mat(0x252b29,.48,.52), gunEdge=mat(0x414844,.36,.68), gripMat=mat(0x171c1b,.8,.1), accent=mat(0x89927d,.4,.55);
box(gun,[.22,.2,.72],gunBody,[0,0,0]); box(gun,[.25,.12,.43],gunEdge,[0,.02,-.16]); box(gun,[.18,.16,.13],gripMat,[0,-.16,.11],[.16,0,0]);
box(gun,[.13,.37,.18],gripMat,[0,-.25,-.08],[.16,0,0]); box(gun,[.12,.06,.65],gunEdge,[0,.13,-.04]);
const barrelMesh=new THREE.Mesh(new THREE.CylinderGeometry(.035,.045,.52,10),gunEdge);barrelMesh.rotation.x=Math.PI/2;barrelMesh.position.set(0,.01,-.55);gun.add(barrelMesh);
box(gun,[.16,.12,.14],gunBody,[0,.015,-.82]); box(gun,[.18,.04,.24],gunBody,[0,-.01,-.36]);
box(gun,[.1,.1,.04],accent,[0,.2,-.25]); box(gun,[.08,.12,.05],gunBody,[0,.2,-.77]);
for(let i=0;i<5;i++)box(gun,[.035,.035,.035],accent,[-.09+i*.045,.13,-.22]);
const bolt=box(gun,[.02,.04,.19],accent,[.125,.025,-.05]);
// Handguard grooves
for(let i=0;i<5;i++)box(gun,[.235,.018,.018],gripMat,[0,.085,-.37+i*.065]);
const muzzleFlash=new THREE.Group();gun.add(muzzleFlash);muzzleFlash.position.set(0,.01,-1.03);const flashMat=new THREE.MeshBasicMaterial({color:0xffc477,transparent:true,opacity:.9,side:THREE.DoubleSide});const flash=new THREE.Mesh(new THREE.ConeGeometry(.12,.38,8),flashMat);flash.rotation.x=Math.PI/2; muzzleFlash.add(flash);muzzleFlash.visible=false;
const flashLight=new THREE.PointLight(0xffab5c,0,4);flashLight.position.copy(muzzleFlash.position);gun.add(flashLight);

