)' opacity='.4'/%3E%3C/svg%3E")}.screen-content{position:relative;width:min(560px,90vw);margin-left:max(7vw,34px);margin-right:auto;animation:arrive .8s cubic-bezier(.15,.7,.2,1) both}.eyebrow{display:flex;align-items:center;gap:12px;color:var(--acid);font:600 11px 'Rajdhani',sans-serif;letter-spacing:.19em}.eyebrow span{display:inline-block;width:25px;height:1px;background:var(--acid);opacity:.75}.screen h1{font:900 clamp(74px,11vw,142px)/.8 'Barlow Condensed',sans-serif;letter-spacing:-.055em;margin:28px 0 0;text-shadow:0 6px 45px rgba(0,0,0,.55)}.screen h1 span{display:block;color:var(--acid)}.subtitle{font:700 19px 'Rajdhani',sans-serif;letter-spacing:.47em;margin:21px 0 30px 6px;color:#d9ded0}.story{font:500 17px/1.35 'Rajdhani',sans-serif;letter-spacing:.04em;color:rgba(235,240,229,.74);margin:0 0 35px 5px}.primary-button{position:relative;display:flex;align-items:center;justify-content:space-between;width:212px;height:58px;padding:0 20px 0 25px;border:1px solid rgba(207,229,144,.75);background:rgba(186,213,104,.11);color:#eaf1dd;cursor:pointer;font:700 15px 'Rajdhani',sans-serif;letter-spacing:.2em;transition:.2s;clip-path:polygon(0 0,92% 0,100% 24%,100% 100%,8% 100%,0 77%)}.primary-button:before{content:'';position:absolute;inset:0;background:var(--acid);transform:scaleX(0);transform-origin:left;transition:transform .24s;z-index:-1}.primary-button:hover{color:#111;box-shadow:0 0 35px rgba(196,227,124,.18)}.primary-button:hover:before{transform:scaleX(1)}.primary-button b{font-size:23px;font-weight:500;color:var(--acid)}.primary-button:hover b{color:#111}.start-meta{margin-top:37px;color:rgba(222,231,216,.63);font:600 10px 'Rajdhani',sans-serif;letter-spacing:.13em}.start-meta span{color:var(--orange);font-size:15px;vertical-align:-2px;margin-right:8px}.start-meta i{display:inline-block;width:3px;height:3px;background:var(--acid);border-radius:50%;margin:0 11px 2px}.desktop-instructions,.mobile-instructions{margin-top:44px;color:rgba(222,231,216,.45);font:500